import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.logging.Logger;
import java.nio.file.StandardCopyOption;
import java.util.stream.Stream;

public static boolean copyFolder(File source, File target, Logger log) {
    Path sourcePath = source.toPath();
    Path destPath = target.toPath();
    try (Stream<Path> files = Files.walk(sourcePath)) {
        files.forEachOrdered(src -> {
            try {
                Path targetPath = destPath.resolve(sourcePath.relativize(src));
                if (Files.isDirectory(src)) {
                    // Create the directory if it doesn't exist
                    if (!Files.exists(targetPath)) {
                        Files.createDirectories(targetPath);
                    }
                } else {
                    // Ensure the parent directory exists before copying
                    Files.createDirectories(targetPath.getParent());
                    // Copy the file
                    Files.copy(src, targetPath, StandardCopyOption.REPLACE_EXISTING);
                }
            } catch (IOException e) {
                log.warning("Failed to copy: " + src + " - " + e.getMessage());
                // We should indicate failure and stop processing further
                throw new RuntimeException("Failed to copy folder", e);
            }
        });
        return true;
    } catch (IOException | RuntimeException e) {
        log.warning("Copy operation failed: " + e.getMessage());
        return false;
    }
}

